package com.tao.fenuasmash.match;

import java.time.Instant;
import java.util.UUID;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotNull;

/**
 * @param id generated by the tablet, kept when the event is sent again
 * @param sequence position of the event in the match, from 1, without gaps
 * @param side the side that won the rally: required for a point, absent for an undo
 * @param occurredAt when the umpire entered the event, from the tablet clock
 */
public record ScoreEventRequest(
		@NotNull UUID id,
		@NotNull @Min(1) Integer sequence,
		@NotNull ScoreEventType type,
		MatchSide side,
		@NotNull Instant occurredAt) {
}
